-- ============================================
-- Saved Assignment Microtasks (#42)
-- ============================================

-- Microtasks are generated by the backend and saved once.
-- Stable IDs allow completion, progress, and study sessions to reference them.
create table public.assignment_microtasks (
    id uuid primary key default gen_random_uuid(),
    assignment_id uuid not null
        references public.assignments(id) on delete cascade,
    user_id uuid not null
        references auth.users(id) on delete cascade,

    title text not null
        check (char_length(trim(title)) between 1 and 200),

    -- Tasks are displayed in this order, beginning at 1.
    position integer not null
        check (position between 1 and 12),

    estimated_minutes integer not null
        check (estimated_minutes between 1 and 6000),

    -- Reserved for the microtask-completion story.
    completed boolean not null default false,

    -- Remember which assignment instructions and total produced this plan.
    -- This lets the backend detect an outdated plan without deleting work.
    source_basis text not null,
    plan_total_minutes integer not null
        check (plan_total_minutes between 5 and 6000),

    created_at timestamptz not null default now(),

    -- Prevent duplicate positions for the same assignment.
    unique (assignment_id, position)
);

create index assignment_microtasks_user_id_idx
on public.assignment_microtasks(user_id);

alter table public.assignment_microtasks enable row level security;

-- Students can read only their own tasks for their own assignments.
-- Removed assignments and disabled courses remain hidden.
create policy "Users can view their own assignment microtasks"
on public.assignment_microtasks
for select
to authenticated
using (
    user_id = (select auth.uid())
    and exists (
        select 1
        from public.assignments as assignment
        where assignment.id = assignment_microtasks.assignment_id
          and assignment.user_id = (select auth.uid())
          and assignment.removed_at is null
          and (
              assignment.course_id is null
              or exists (
                  select 1
                  from public.courses as course
                  where course.id = assignment.course_id
                    and course.user_id = (select auth.uid())
                    and course.sync_enabled = true
              )
          )
    )
);

-- The app reads tasks. The authenticated backend saves generated plans.
-- Completion updates will be added through the completion story.
revoke all on table public.assignment_microtasks
from public, anon, authenticated;

grant select on table public.assignment_microtasks
to authenticated;

grant all on table public.assignment_microtasks
to service_role;

-- ============================================
-- Save a Complete Microtask Plan
-- ============================================

-- Only the backend can call this function.
-- It saves every task together, or saves nothing if validation fails.
create function public.save_assignment_microtasks(
    p_assignment_id uuid,
    p_user_id uuid,
    p_title text,
    p_description text,
    p_total_minutes integer,
    p_tasks jsonb
)
returns boolean
language plpgsql
security invoker
set search_path = ''
as $$
declare
    saved_assignment public.assignments%rowtype;
    current_basis text;
    task_count integer;
    total_minutes numeric;
begin
    -- Lock this assignment while checking and saving its plan.
    -- Two requests cannot save different plans at the same time.
    select assignment.*
    into saved_assignment
    from public.assignments as assignment
    where assignment.id = p_assignment_id
    for update;

    if not found then
        raise exception 'Assignment is unavailable.';
    end if;

    -- The backend passes the ID of the authenticated student.
    if p_user_id is null
        or saved_assignment.user_id is distinct from p_user_id
        or saved_assignment.removed_at is not null then
        raise exception 'Assignment is unavailable.';
    end if;

    if saved_assignment.course_id is not null
        and not exists (
            select 1
            from public.courses as course
            where course.id = saved_assignment.course_id
              and course.user_id = p_user_id
              and course.sync_enabled = true
        ) then
        raise exception 'This course is not available for syncing.';
    end if;

    -- Never replace saved tasks or their completion history.
    -- False means another plan already exists.
    if exists (
        select 1
        from public.assignment_microtasks as task
        where task.assignment_id = p_assignment_id
    ) then
        return false;
    end if;

    -- A plan must use the assignment's actual saved time estimate.
    if p_total_minutes is null
        or p_total_minutes not between 5 and 6000
        or saved_assignment.estimated_minutes
            is distinct from p_total_minutes then
        raise exception 'The assignment estimate changed or is unavailable.';
    end if;

    current_basis := public.assignment_estimate_basis(
        saved_assignment.title,
        saved_assignment.description
    );

    -- Do not save a response generated from older assignment instructions.
    if current_basis is distinct from public.assignment_estimate_basis(
        p_title,
        p_description
    ) then
        raise exception 'The assignment instructions changed. Please retry.';
    end if;

    if p_tasks is null
        or jsonb_typeof(p_tasks) is distinct from 'array' then
        raise exception 'Expected a list of microtasks.';
    end if;

    task_count := jsonb_array_length(p_tasks);

    if task_count not between 1 and 12 then
        raise exception 'A plan must contain between 1 and 12 microtasks.';
    end if;

    -- Validate text and whole-minute durations before converting values.
    if exists (
        select 1
        from jsonb_array_elements(p_tasks) as item(task)
        where jsonb_typeof(task) is distinct from 'object'
           or jsonb_typeof(task -> 'title') is distinct from 'string'
           or char_length(trim(task ->> 'title')) not between 1 and 200
           or jsonb_typeof(task -> 'minutes') is distinct from 'number'
           or coalesce(task ->> 'minutes', '') !~ '^[0-9]+$'
    ) then
        raise exception 'Each microtask needs a title and whole-minute duration.';
    end if;

    if exists (
        select 1
        from jsonb_array_elements(p_tasks) as item(task)
        where (task ->> 'minutes')::numeric not between 1 and 6000
    ) then
        raise exception 'Microtask durations must be positive and within limits.';
    end if;

    -- Duplicate task titles usually indicate an unusable AI response.
    if exists (
        select 1
        from jsonb_array_elements(p_tasks) as item(task)
        group by lower(
            regexp_replace(trim(task ->> 'title'), '\s+', ' ', 'g')
        )
        having count(*) > 1
    ) then
        raise exception 'Microtask titles must be distinct.';
    end if;

    select sum((task ->> 'minutes')::numeric)
    into total_minutes
    from jsonb_array_elements(p_tasks) as item(task);

    if total_minutes is distinct from p_total_minutes::numeric then
        raise exception 'Microtask minutes must equal the assignment estimate.';
    end if;

    -- Array order becomes the saved task order, starting at 1.
    -- One insert saves the entire validated plan.
    insert into public.assignment_microtasks (
        assignment_id,
        user_id,
        title,
        position,
        estimated_minutes,
        source_basis,
        plan_total_minutes
    )
    select
        p_assignment_id,
        p_user_id,
        trim(task ->> 'title'),
        task_position::integer,
        (task ->> 'minutes')::integer,
        current_basis,
        p_total_minutes
    from jsonb_array_elements(p_tasks)
        with ordinality as item(task, task_position);

    return true;
end;
$$;

-- Keep this operation unavailable to the mobile app and anonymous callers.
-- The Edge Function will authenticate the student before calling it.
revoke execute on function public.save_assignment_microtasks(
    uuid, uuid, text, text, integer, jsonb
) from public, anon, authenticated;

grant execute on function public.save_assignment_microtasks(
    uuid, uuid, text, text, integer, jsonb
) to service_role;